/**
 * ROUTING CASES: what a person says, which apps they have connected, and the
 * one app (and, for our own apps, the one tool) the assistant should reach
 * for first. connector-routing.test.ts runs the router over these.
 *
 * `connected` lists catalog ids (catalog.ts CATALOG) in the order the person
 * connected them. The hand-offs (ALWAYS_ON: email-handoff, whatsapp,
 * telegram, phone, upi, maps, uber, shopping, play, threads, booking,
 * youtube) are always there and are never listed.
 *
 * `expect.app: null` means no app: the request is about the screen, general
 * knowledge, or an app that is not connected (the assistant should SAY which
 * app to connect, never put it somewhere else). `expect.tool` is the tool
 * that must come first among the app's cards and be offered as "pick:": for
 * our own apps (Google natives and hand-offs) against their real tool lists,
 * for an MCP app against the stand-in list in connector-routing.test.ts (the
 * names its vendor's server publishes). `expect.also` is a second app a
 * request asks for in the same breath ("move the standup and tell the team on
 * slack"); `expect.pick: false` is a request for two changes of one app, which
 * gets both tools and no "pick:" line; `expect.quiet` is a question about
 * apps, which must get no "connect X" line.
 *
 * THE GROUND-TRUTH POLICY these cases follow, in order:
 *   1. An app named outright wins ("in Notion", "on telegram", "via zapier").
 *      Named but not connected: no app (say "connect X"), never a stand-in.
 *      Slack, which Tailzu reaches only through Zapier, is Zapier's.
 *   2. Otherwise the job decides the kind of app: an event at a time is the
 *      calendar; a reminder or to-do the tasks app; a note the notes app; a
 *      document Docs; a message WhatsApp; a "text message"/SMS the phone; an
 *      email the Gmail hand-off; and so on.
 *   3. Several connected apps of that kind: the one used in the last week
 *      (`recent`), else a fixed order per kind:
 *        tasks         todoist > google-tasks > asana > clickup   (Todoist keeps the time of a reminder; Google Tasks keeps only the day. Notion is never a reminder app.)
 *        notes         evernote > notion > google-docs
 *        documents     google-docs > notion
 *        issues        linear > atlassian > github  (github for repo, PR, commit, branch)
 *        meeting notes granola > fireflies > otter
 *        booking links calendly > calcom          (the person's own events are always google-calendar)
 *        boards        trello > monday > clickup
 *        tables        google-sheets > airtable
 *   4. An automation hub (zapier, make, composio, pipedream) only when named,
 *      or when nothing else connected can do the job.
 *   5. A word that only looks like an app ("make a quiz", "monday morning",
 *      "the notion of time", "tell me a joke") is not that app.
 */

export type Kind =
  | "calendar" | "tasks" | "notes" | "docs" | "sheets" | "forms" | "classroom"
  | "projects" | "meeting-notes" | "booking-links" | "automation"
  | "message" | "email" | "call" | "pay" | "travel" | "shopping" | "play" | "social"
  | "named" | "overlap" | "followup" | "lookalike" | "nothing" | "not-connected"
  // Round two of the review: misspelt, two requests in one, an app named inside what is said, a question about apps.
  | "typo" | "two-in-one" | "inside" | "opinion";

export interface RoutingCase {
  said: string;
  connected: string[];
  expect: { app: string | null; tool?: string; also?: string; pick?: false; quiet?: true };
  /** What the case tests, for the report. */
  kind: Kind;
  /** "hi" for Hinglish. Default English. */
  lang?: "hi";
  /** What they said earlier in this ask (the phone routes by all of it). */
  history?: string[];
  /** The app in front of them. Default "Tailzu" (the phone's ask). */
  front?: string;
  /** Hours since an app was last used, by id. */
  recent?: Record<string, number>;
}

